import{_ as t,o as a,c as s,a2 as n}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Frontend Stack","description":"","frontmatter":{},"headers":[],"relativePath":"guide/frontend-stack.md","filePath":"guide/frontend-stack.md","lastUpdated":1787151563000}'),r={name:"guide/frontend-stack.md"};function d(o,e,i,c,l,p){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="frontend-stack" tabindex="-1">Frontend Stack <a class="header-anchor" href="#frontend-stack" aria-label="Permalink to &quot;Frontend Stack&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>Frontend 是 Vue 3 SPA，以 Pinia 管理狀態、Vue Router 管理路由，Capacitor 包裝為 Android App。程式碼分為 <code>ui/</code>（呈現）、<code>core/</code>（領域邏輯）、<code>services/</code>（對外 API client）。</p><h2 id="目錄結構" tabindex="-1">目錄結構 <a class="header-anchor" href="#目錄結構" aria-label="Permalink to &quot;目錄結構&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>frontend/src/</span></span>
<span class="line"><span>├── main.js                 # App 入口</span></span>
<span class="line"><span>├── core/</span></span>
<span class="line"><span>│   ├── db/                 # SQLite 連線、migration</span></span>
<span class="line"><span>│   ├── repositories/       # 資料存取</span></span>
<span class="line"><span>│   ├── services/           # 業務邏輯</span></span>
<span class="line"><span>│   ├── domain/             # 純函式領域規則</span></span>
<span class="line"><span>│   └── utils/</span></span>
<span class="line"><span>├── ui/</span></span>
<span class="line"><span>│   ├── views/              # 頁面</span></span>
<span class="line"><span>│   ├── components/         # 共用元件</span></span>
<span class="line"><span>│   ├── stores/             # Pinia</span></span>
<span class="line"><span>│   ├── services/           # runtime / sync / 平台</span></span>
<span class="line"><span>│   ├── router/</span></span>
<span class="line"><span>│   └── composables/</span></span>
<span class="line"><span>└── services/               # backend / Google HTTP client</span></span></code></pre></div><h2 id="pinia-store-職責" tabindex="-1">Pinia Store 職責 <a class="header-anchor" href="#pinia-store-職責" aria-label="Permalink to &quot;Pinia Store 職責&quot;">​</a></h2><p>目錄：<a href="https://github.com/StrawCoding/StrawMoneyBook/tree/main/frontend/src/ui/stores" target="_blank" rel="noreferrer"><code>frontend/src/ui/stores/</code></a></p><table tabindex="0"><thead><tr><th>Store</th><th>職責</th></tr></thead><tbody><tr><td><code>ledger.store</code></td><td>活動帳本、帳本 CRUD、預算期間模式設定</td></tr><tr><td><code>account.store</code></td><td>帳戶清單、餘額、群組統計（含匯率換算）</td></tr><tr><td><code>category.store</code></td><td>分類樹</td></tr><tr><td><code>transaction.store</code></td><td>交易載入、首頁篩選、CRUD action</td></tr><tr><td><code>budget.store</code></td><td>預算期間、共同池、項目、getter（已用/剩餘/保留）</td></tr><tr><td><code>loan.store</code></td><td>借貸清單、還款、作廢</td></tr><tr><td><code>reimbursement.store</code></td><td>報銷列表、自訂報銷金額</td></tr><tr><td><code>addon-template.store</code></td><td>附加項目模板快取</td></tr><tr><td><code>ui.store</code></td><td>Toast 等全域 UI 狀態</td></tr></tbody></table><p>Store action 應<strong>委派</strong> Core Service，避免在 Store 內寫業務規則。</p><h2 id="查詢單一入口" tabindex="-1">查詢單一入口 <a class="header-anchor" href="#查詢單一入口" aria-label="Permalink to &quot;查詢單一入口&quot;">​</a></h2><p><a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/frontend/src/core/services/transaction-query.service.js" target="_blank" rel="noreferrer"><code>transaction-query.service.js</code></a> 統一：</p><ul><li>首頁交易流（SQL 分頁，每頁 300 筆）</li><li>分析、搜尋、日曆、帳戶明細、交易編輯關聯載入</li></ul><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Home[home.vue]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Analysis[analysis.vue]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Search[TransactionSearchPage]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  TQS[transaction-query.service]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Repo[transaction.repo]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Home --&gt; TQS</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Analysis --&gt; TQS</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Search --&gt; TQS</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  TQS --&gt; Repo</span></span></code></pre></div><h2 id="路由與-app-shell" tabindex="-1">路由與 App Shell <a class="header-anchor" href="#路由與-app-shell" aria-label="Permalink to &quot;路由與 App Shell&quot;">​</a></h2><p>路由定義：<a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/frontend/src/ui/router/index.js" target="_blank" rel="noreferrer"><code>ui/router/index.js</code></a></p><ul><li>5 tab 底部導覽：首頁、預算、分析、功能列表、設定</li><li>記帳三模式共用 <code>BookkeepingPage.vue</code>（AI / 手動 / 問答）</li><li>Deep link：<code>/open/shared-ledger</code>、<code>/shared-ledger/join</code> redirect 到設定頁</li></ul><p><a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/frontend/src/ui/App.vue" target="_blank" rel="noreferrer"><code>App.vue</code></a> 控制 Welcome wizard、BottomNav、安全鎖 overlay。</p><h2 id="ui-service-層-平台與-runtime" tabindex="-1">UI Service 層（平台與 Runtime） <a class="header-anchor" href="#ui-service-層-平台與-runtime" aria-label="Permalink to &quot;UI Service 層（平台與 Runtime）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Service</th><th>用途</th></tr></thead><tbody><tr><td><code>app-bootstrap.service</code></td><td>UI 啟動鏈</td></tr><tr><td><code>app-runtime.service</code></td><td>前景事件、背景排程</td></tr><tr><td><code>ledger-runtime.service</code></td><td>帳本 lifecycle</td></tr><tr><td><code>shared-ledger.service</code></td><td>共同帳本流程</td></tr><tr><td><code>google-drive-ledger-sync.service</code></td><td>GDrive 帳本同步</td></tr><tr><td><code>google-backup.service</code> / <code>webdav-backup.service</code></td><td>自動備份</td></tr><tr><td><code>theme.service</code> / <code>ui-layout.service</code></td><td>主題與 modern-only UI</td></tr><tr><td><code>security-lock.service</code></td><td>生物辨識鎖</td></tr></tbody></table><h2 id="主要-core-service-節錄" tabindex="-1">主要 Core Service（節錄） <a class="header-anchor" href="#主要-core-service-節錄" aria-label="Permalink to &quot;主要 Core Service（節錄）&quot;">​</a></h2><p>完整清單見 <a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/frontend/StrawMoneyBook_Features_Map.md" target="_blank" rel="noreferrer"><code>StrawMoneyBook_Features_Map.md</code> §7</a>。</p><table tabindex="0"><thead><tr><th>Service</th><th>域</th></tr></thead><tbody><tr><td><code>transaction.service</code></td><td>記帳 CRUD、退款</td></tr><tr><td><code>budget.service</code> / <code>budget-save.service</code></td><td>預算與自動存罐</td></tr><tr><td><code>loan.service</code></td><td>借貸</td></tr><tr><td><code>reimbursement.service</code></td><td>報銷</td></tr><tr><td><code>ai-bookkeeping.service</code></td><td>AI 解析</td></tr><tr><td><code>membership.service</code></td><td>會員限制</td></tr><tr><td><code>import.service</code> / <code>export.service</code></td><td>匯入匯出</td></tr></tbody></table><h2 id="測試" tabindex="-1">測試 <a class="header-anchor" href="#測試" aria-label="Permalink to &quot;測試&quot;">​</a></h2><ul><li>Node test runner：<code>frontend/test/*.test.js</code></li><li>Playwright UI：<code>frontend</code> 內 playwright 腳本（layout、bank-sync 等）</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/guide/backend-api.html">Backend API</a></li><li><a href="/domains/bookkeeping.html">Bookkeeping</a></li></ul>`,26)])])}const k=t(r,[["render",d]]);export{u as __pageData,k as default};
